      center=`<rect x="20" y="31" width="60" height="80" rx="2" fill="#f0e8d5" stroke="#d7ceb9" stroke-width="1"/><g transform="translate(50 72)">${royal}</g><g transform="translate(50 72) rotate(180)">${royal}</g><path d="m23 70 54 4" stroke="#ddc58e" stroke-width="2"/>${pip(50,73,false,21)}`;
