    $('undo-button').disabled=!history.length||autoRunning;$('auto-button').disabled=!E.canAutoFinish(game)||autoRunning||game.status==='won';$('hint-button').disabled=autoRunning||game.status==='won';$('new-button').disabled=autoRunning;
    $('auto-button').title=t('autoNote');$('board').setAttribute('aria-label',t('board'));
